cd /tmp && node -e '
let ranges=[],start=-1;
for(let cp=0;cp<=0x10FFFF;cp++){
  const isNd=/\p{Nd}/u.test(String.fromCodePoint(cp));
  if(isNd&&start<0)start=cp;
  else if(!isNd&&start>=0){ranges.push([start,cp-1]);start=-1;}
}
if(start>=0)ranges.push([start,0x10FFFF]);
const H=n=>n.toString(16).toUpperCase().padStart(4,"0");
console.log("node ranges="+ranges.length+"  total cps="+ranges.reduce((a,[s,e])=>a+e-s+1,0));
